// Circuit breaker: if Account Service is down, fall back to cached/error
package com.bank.payment.service;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import io.github.resilience4j.retry.annotation.Retry;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;
import java.math.BigDecimal;

@Service
@Slf4j
public class AccountClient {

    private final RestClient restClient;

    public AccountClient() {
        this.restClient = RestClient.builder()
            .baseUrl("http://account-service:8200")
            .build();
    }

    @CircuitBreaker(name = "accountService", fallbackMethod = "debitFallback")
    @Retry(name = "accountService")
    public boolean debit(String accountId, BigDecimal amount) {
        log.info("Calling Account Service: debit {} Rs.{}", accountId, amount);
        // Real: restClient.post().uri("/api/v1/accounts/{id}/debit", accountId)...
        return true; // simplified
    }

    @CircuitBreaker(name = "accountService", fallbackMethod = "creditFallback")
    @Retry(name = "accountService")
    public boolean credit(String accountId, BigDecimal amount) {
        log.info("Calling Account Service: credit {} Rs.{}", accountId, amount);
        return true;
    }

    // SAGA COMPENSATION: if credit fails, re-credit the debited account
    public boolean compensateDebit(String accountId, BigDecimal amount) {
        log.warn("SAGA COMPENSATION: re-crediting {} Rs.{}", accountId, amount);
        return credit(accountId, amount);
    }

    // Fallbacks when circuit breaker is OPEN
    private boolean debitFallback(String accountId, BigDecimal amount, Exception e) {
        log.error("CIRCUIT OPEN: Account Service unavailable for debit {}: {}", accountId, e.getMessage());
        return false;
    }

    private boolean creditFallback(String accountId, BigDecimal amount, Exception e) {
        log.error("CIRCUIT OPEN: Account Service unavailable for credit {}: {}", accountId, e.getMessage());
        return false;
    }
}
