// IDEMPOTENCY + SAGA in one service
package com.bank.payment.service;

import com.bank.payment.dto.*;
import com.bank.payment.model.*;
import com.bank.payment.repository.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.Optional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class PaymentService {

    private final PaymentRepository paymentRepo;
    private final IdempotencyRepository idempotencyRepo;
    private final AccountClient accountClient;
    private final KafkaTemplate<String, Object> kafkaTemplate;
    private final ObjectMapper objectMapper;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // ─── IDEMPOTENCY CHECK: if already processed, return stored response ───
        Optional<IdempotencyRecord> existing = idempotencyRepo.findByIdempotencyKey(request.idempotencyKey());
        if (existing.isPresent()) {
            log.info("IDEMPOTENT: already processed key={}, returning stored response", request.idempotencyKey());
            try {
                return objectMapper.readValue(existing.get().getResponseJson(), PaymentResponse.class);
            } catch (Exception e) {
                throw new RuntimeException("Failed to deserialize stored response", e);
            }
        }

        // ─── CREATE PAYMENT ───
        String paymentId = "PAY-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        Payment payment = new Payment(paymentId, request.fromAccount(), request.toAccount(),
            request.amount(), request.method(), request.idempotencyKey());
        paymentRepo.save(payment);

        // ─── SAGA STEP 1: Debit sender (via Account Service + Circuit Breaker) ───
        boolean debited = accountClient.debit(request.fromAccount(), request.amount());
        if (!debited) {
            payment.fail();
            paymentRepo.save(payment);
            return saveAndReturnResponse(payment, request.idempotencyKey());
        }

        // ─── SAGA STEP 2: Credit receiver ───
        boolean credited = accountClient.credit(request.toAccount(), request.amount());
        if (!credited) {
            // SAGA COMPENSATION: debit succeeded but credit failed → reverse the debit
            log.warn("SAGA: Credit failed → compensating debit for {}", request.fromAccount());
            accountClient.compensateDebit(request.fromAccount(), request.amount());
            payment.compensate();
            paymentRepo.save(payment);
            return saveAndReturnResponse(payment, request.idempotencyKey());
        }

        // ─── SUCCESS ───
        payment.complete();
        paymentRepo.save(payment);

        // ─── PUBLISH EVENT (async — Kafka) ───
        kafkaTemplate.send("payment-events", paymentId,
            new PaymentResponse(paymentId, request.fromAccount(), request.toAccount(),
                request.amount(), "COMPLETED"));
        log.info("Payment {} completed → event published to Kafka", paymentId);

        return saveAndReturnResponse(payment, request.idempotencyKey());
    }

    private PaymentResponse saveAndReturnResponse(Payment payment, String idempotencyKey) {
        PaymentResponse response = PaymentResponse.from(payment);
        try {
            String json = objectMapper.writeValueAsString(response);
            idempotencyRepo.save(new IdempotencyRecord(idempotencyKey, payment.getPaymentId(), json));
        } catch (Exception e) {
            log.error("Failed to save idempotency record", e);
        }
        return response;
    }
}
